#include "led.h"
#include "timer.h"
#include "uart.h"
#include <stdint.h>
#include <string.h>
#include "stm32c031xx.h"

int main(void)
{
    uart_init();
    timer_init();
    led_init();

    char c [10];
    char *ptr = c;
    char a;

    uint8_t last_was_cr = 0;
    uint8_t command_overflow = 0;

    uart_write_string("UART ready");
    uart_write_string("\r\n");


    while (1)
    {
       if (uart_char_available())
       {
            a = uart_read_char();
            if (last_was_cr && a == '\n')
            {
                last_was_cr = 0;
                continue;
            }

            last_was_cr = 0;

            if (a == '\r' || a == '\n')
            {
                last_was_cr = (a == '\r');
                *ptr = '\0';

                if (command_overflow == 1)
                {
                    uart_write_string("Error: command too long\r\n");
                }

                else
                {
                    uart_write_string(c);
                    uart_write_string("\r\n");

                    if (strcmp(c, "led on") == 0)
                    {
                        led_on();
                    }

                    else if (strcmp(c, "led off") == 0)
                    {
                        led_off();
                    }

                    else if (strcmp(c, "status") == 0)
                    {
                        if (TIM3->CR1 & (1U << 0))
                        {
                            uart_write_string("Timer: running\r\n");
                        }
                        else
                        {
                            uart_write_string("Timer: stopped\r\n");
                        }
                    }
                }

                ptr = c;
                command_overflow = 0;
            }

            else
            {
                if (ptr < (c + 9))
                {
                    *ptr = a;
                    ptr++;
                }
                else
                {
                    command_overflow = 1;
                }
            }
       }
    }
}